    state_t state;

    integer j;
    logic [WIDTH-1:0] i;
    logic [WIDTH-1:0] a[42];
    logic [WIDTH-1:0] sum;


     always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            i     <= 0;
            sum   <= 0;
            state <= LOOP;
            for (j = 0; j < 42; j++) begin
                a[j] = 0;
            end
        end else begin
            case (state)
                LOOP: begin
                    if (i < 42) begin
                        i     <= i+1;
                        if (i % 1 == 0) begin
                          a[i] <= 1;
                          sum <= sum + 1;
                        end
                    end
                    else begin
                        state <= DONE;
                    end
                end
            endcase
        end
    end


    property prop;
        @(posedge clk) disable iff (rst) sum <= 42;
    endproperty


endmodule

response.text:
The useful strengthening is **counter boundedness plus counter equality**. Both use the property’s clock and reset convention. ([accellera.org](https://www.accellera.org/images/resources/videos/SystemVerilog_Assertions_Tutorial_2016.pdf?utm_source=openai))

<json>
{
  "lemmas": [
    {
      "lemma": "property lemma_1; @(posedge clk) disable iff (rst) i <= 42; endproperty",
      "explanation": "Reset sets i to zero. It increments only while below 42, and otherwise holds, so this bound is inductive."
    },
    {
      "lemma": "property lemma_2; @(posedge clk) disable iff (rst) sum == i; endproperty",
      "explanation": "Reset makes both registers zero. Since i % 1 is always zero, every update increments both registers by one; otherwise both hold. This equality and lemma_1 imply sum <= 42."
    }
  ]
}
</json>

The proof requires a reset to have occurred; arbitrary unreset register values need not satisfy these invariants.
